    "artist": "Édouard Manet",
    "artistSort": "manet edouard manet",
    "year": "1864",
    "yearStart": 1864,
    "yearEnd": 1864,
    "era": "1850–1879",
    "theme": "Still Life & Flowers",
    "medium": "Oil on canvas",
    "imageUrl": "/artworks/aic-44892.webp",
