    "artist": "Hubert Robert",
    "artistSort": "robert hubert robert",
    "year": "1787–88",
    "yearStart": 1787,
    "yearEnd": 1788,
    "era": "1700s",
    "theme": "People & Daily Life",
    "medium": "Oil on canvas",
    "imageUrl": "/artworks/aic-57051.webp",
