    "id": "aic-44198",
    "title": "Sugawara Michizane Going into Exile",
    "artist": "Suzuki Harunobu",
    "artistSort": "harunobu suzuki harunobu",
    "year": "c. 1763/64",
    "yearStart": 1758,
    "yearEnd": 1769,
    "era": "1700s",
    "theme": "Japanese Prints",
    "medium": "Color woodblock print; hosoban, mizu-e",
    "imageUrl": "/artworks/aic-44198.webp",
    "thumbnailUrl": "/artworks/aic-44198-thumb.webp",
    "width": 562,
    "height": 1200,
    "museum": "Art Institute of Chicago",
